DO $$ BEGIN CREATE TYPE "public"."recipe_status" AS ENUM('draft', 'published', 'failed'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "public"."tip_type" AS ENUM('dica', 'tecnica', 'materia'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "authors" ("id" integer PRIMARY KEY, "slug" varchar(180) NOT NULL, "name" varchar(180) NOT NULL, "bio" text, "avatar_url" text, "role" varchar(80), "active" boolean DEFAULT true NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "authors_slug_uidx" ON "authors" ("slug");
CREATE TABLE IF NOT EXISTS "categories" ("id" integer PRIMARY KEY, "slug" varchar(180) NOT NULL, "name" varchar(180) NOT NULL, "parent_id" integer, "active" boolean DEFAULT true NOT NULL, "risk_level" varchar(24), "agent_enabled" boolean DEFAULT true NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "categories_slug_uidx" ON "categories" ("slug");
CREATE TABLE IF NOT EXISTS "tip_topics" ("id" integer PRIMARY KEY, "slug" varchar(180) NOT NULL, "name" varchar(180) NOT NULL, "description" text, "active" boolean DEFAULT true NOT NULL, "sort_order" integer DEFAULT 0 NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "tip_topics_slug_uidx" ON "tip_topics" ("slug");
CREATE TABLE IF NOT EXISTS "tags" ("id" integer PRIMARY KEY, "slug" varchar(120) NOT NULL, "name" varchar(120) NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "tags_slug_uidx" ON "tags" ("slug");
CREATE TABLE IF NOT EXISTS "images" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "file_url" text NOT NULL, "storage_key" text, "file_name" varchar(255), "alt_text" varchar(240), "caption" text, "content_type" varchar(120), "file_size" bigint, "width" integer, "height" integer, "image_type" varchar(40), "source_type" varchar(40), "generation_meta" jsonb, "active" boolean DEFAULT true NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
ALTER TABLE "recipes" ADD COLUMN IF NOT EXISTS "author_id" integer;
ALTER TABLE "recipes" ADD COLUMN IF NOT EXISTS "agent_topic_slug" varchar(180);
ALTER TABLE "recipes" ADD COLUMN IF NOT EXISTS "agent_idempotency_key" varchar(64);
ALTER TABLE "recipes" ADD COLUMN IF NOT EXISTS "agent_request_hash" varchar(64);
CREATE UNIQUE INDEX IF NOT EXISTS "recipes_agent_idempotency_key_uidx" ON "recipes" ("agent_idempotency_key") WHERE "agent_idempotency_key" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "recipes_agent_topic_slug_uidx" ON "recipes" ("agent_topic_slug") WHERE "agent_topic_slug" IS NOT NULL;
CREATE TABLE IF NOT EXISTS "tips" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "slug" varchar(180) NOT NULL, "title" varchar(180) NOT NULL, "excerpt" text NOT NULL, "content" text NOT NULL, "tip_type" "tip_type" NOT NULL, "tip_topic" varchar(180), "author_id" integer NOT NULL, "cover_image_url" text, "cover_image_alt" varchar(240), "meta_title" varchar(180), "meta_description" varchar(320), "canonical_url" text, "tags" text[] DEFAULT '{}' NOT NULL, "generation_meta" jsonb DEFAULT '{}'::jsonb NOT NULL, "status" varchar(32) DEFAULT 'draft' NOT NULL, "review_status" varchar(32) DEFAULT 'pending' NOT NULL, "published_at" timestamp with time zone, "agent_topic_slug" varchar(180), "agent_idempotency_key" varchar(128), "agent_request_hash" varchar(64), "created_at" timestamp with time zone DEFAULT now() NOT NULL, "updated_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "tips_slug_uidx" ON "tips" ("slug");
CREATE UNIQUE INDEX IF NOT EXISTS "tips_agent_idempotency_key_uidx" ON "tips" ("agent_idempotency_key") WHERE "agent_idempotency_key" IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "tips_agent_topic_slug_uidx" ON "tips" ("agent_topic_slug") WHERE "agent_topic_slug" IS NOT NULL;
CREATE TABLE IF NOT EXISTS "tip_images" ("id" serial PRIMARY KEY, "tip_id" uuid NOT NULL, "image_id" uuid, "image_url" text, "alt_text" varchar(240), "caption" text, "image_role" varchar(40) DEFAULT 'cover' NOT NULL, "sort_order" integer DEFAULT 0 NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "tip_tags" ("id" serial PRIMARY KEY, "tip_id" uuid NOT NULL, "tag_id" integer NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "tip_tags_tip_tag_uidx" ON "tip_tags" ("tip_id", "tag_id");
CREATE TABLE IF NOT EXISTS "content_relations" ("id" serial PRIMARY KEY, "recipe_id" uuid, "tip_id" uuid, "relation_type" varchar(40) DEFAULT 'related' NOT NULL, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
CREATE TABLE IF NOT EXISTS "content_reports" ("id" serial PRIMARY KEY, "recipe_id" uuid, "tip_id" uuid, "reason" varchar(40) NOT NULL, "details" text, "created_at" timestamp with time zone DEFAULT now() NOT NULL);
